import json
import pandas as pd
from datetime import datetime

def normalize_date(val):
    """Convert any date-like value to YYYY-MM-DD string."""
    if val is None or pd.isna(val):
        return None
    if isinstance(val, datetime):
        return val.strftime("%Y-%m-%d")
    s = str(val).strip()
    # Already in YYYY-MM-DD format
    if len(s) == 10 and s[4] == "-" and s[7] == "-":
        return s
    # Try parsing common formats
    for fmt in ["%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"]:
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s

def normalize_status(val):
    """Normalize active/inactive status to 'active'/'inactive'."""
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return None
    if isinstance(val, bool):
        return "active" if val else "inactive"
    s = str(val).strip().lower()
    if s in ("true", "1", "yes", "active"):
        return "active"
    if s in ("false", "0", "no", "inactive"):
        return "inactive"
    return s

def load_source_a(path):
    with open(path) as f:
        data = json.load(f)
    records = []
    for row in data:
        records.append({
            "user_id": int(row["id"]),
            "name": row.get("full_name"),
            "email": row.get("email"),
            "created_date": normalize_date(row.get("registration_date")),
            "status": normalize_status(row.get("status")),
            "_source": "a",
        })
    return pd.DataFrame(records)

def load_source_b(path):
    df = pd.read_csv(path)
    records = []
    for _, row in df.iterrows():
        records.append({
            "user_id": int(row["user_id"]),
            "name": row.get("name"),
            "email": row.get("email_address"),
            "created_date": normalize_date(row.get("created_at")),
            "status": normalize_status(row.get("is_active")),
            "_source": "b",
        })
    return pd.DataFrame(records)

def load_source_c(path):
    df = pd.read_parquet(path)
    records = []
    for _, row in df.iterrows():
        records.append({
            "user_id": int(row["userId"]),
            "name": row.get("userName"),
            "email": row.get("email"),
            "created_date": normalize_date(row.get("joined")),
            "status": normalize_status(row.get("active")),
            "_source": "c",
        })
    return pd.DataFrame(records)

# Load all sources
df_a = load_source_a("/data/source_a/users.json")
df_b = load_source_b("/data/source_b/users.csv")
df_c = load_source_c("/data/source_c/users.parquet")

print("Source A:")
print(df_a)
print("\nSource B:")
print(df_b)
print("\nSource C:")
print(df_c)

# Combine all records
all_records = pd.concat([df_a, df_b, df_c], ignore_index=True)

# Fields to merge (exclude _source)
merge_fields = ["name", "email", "created_date", "status"]

# Source priority: a=1, b=2, c=3
source_order = {"a": 1, "b": 2, "c": 3}

conflicts = []

# For each user_id, pick the highest-priority source's value per field
merged_rows = []

for user_id, group in all_records.groupby("user_id"):
    group = group.sort_values("_source", key=lambda s: s.map(source_order))
    row = {"user_id": int(user_id)}
    for field in merge_fields:
        # Get non-null values in priority order
        values_by_source = {}
        selected = None
        selected_source = None
        for _, rec in group.iterrows():
            src = rec["_source"]
            val = rec[field]
            # Record the value from this source (may be None/NaN)
            if src not in values_by_source:
                values_by_source[src] = val if not (isinstance(val, float) and pd.isna(val)) else None
            # Pick first non-null value as the winner
            if selected is None and val is not None and not (isinstance(val, float) and pd.isna(val)):
                selected = val
                selected_source = src

        row[field] = selected

        # Check for conflicts: same field has different non-null values across sources
        non_null = {k: v for k, v in values_by_source.items() if v is not None}
        if len(non_null) > 1:
            unique_vals = set(str(v) for v in non_null.values())
            if len(unique_vals) > 1:
                conflict_entry = {
                    "user_id": int(user_id),
                    "field": field,
                    "values": {},
                    "selected": str(selected) if selected is not None else None,
                }
                for src in ["a", "b", "c"]:
                    if src in values_by_source:
                        conflict_entry["values"][f"source_{src}"] = values_by_source[src]
                conflicts.append(conflict_entry)

    merged_rows.append(row)

merged_df = pd.DataFrame(merged_rows)
merged_df = merged_df[["user_id", "name", "email", "created_date", "status"]]

print("\n--- Merged DataFrame ---")
print(merged_df)

# Write parquet output
merged_df.to_parquet("/app/merged_users.parquet", index=False)

# Write conflict report
conflict_report = {
    "total_conflicts": len(conflicts),
    "conflicts": conflicts,
}
with open("/app/conflicts.json", "w") as f:
    json.dump(conflict_report, f, indent=2)

print(f"\nWrote {len(merged_df)} users to /app/merged_users.parquet")
print(f"Conflicts: {len(conflicts)}")
print(json.dumps(conflict_report, indent=2))

